import{at as e,it as t,n,vt as r}from"./chunks/framework.UwwvkjGo.js";var i=JSON.parse(`{"title":"Class: SurfaceSystem","description":"","frontmatter":{},"headers":[],"relativePath":"api/@jsprismarine/worldgen/classes/SurfaceSystem.md","filePath":"api/@jsprismarine/worldgen/classes/SurfaceSystem.md"}`),a={name:`api/@jsprismarine/worldgen/classes/SurfaceSystem.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<p><a href="./../../../">JSPrismarine</a> / <a href="./../">@jsprismarine/worldgen</a> / SurfaceSystem</p><h1 id="class-surfacesystem" tabindex="-1">Class: SurfaceSystem <a class="header-anchor" href="#class-surfacesystem" aria-label="Permalink to “Class: SurfaceSystem”">​</a></h1><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/ef092b0fc8a9901750f1a809082edca449e0675e/packages/worldgen/src/surface/SurfaceSystem.ts#L132" target="_blank" rel="noreferrer">surface/SurfaceSystem.ts:132</a></p><p>The surface pass: the stage that turns a column of stone and water into grass, sand, terracotta bands, bedrock and ore veins.</p><p>It walks each column of a chunk downward, counts how far each solid block sits from the opening above it and the opening below it, and asks the dimension&#39;s material rule tree what to place. The three counters, the randomized surface depth and the preliminary surface level are the whole input the rule tree sees beyond the block position and the biome.</p><p>Two biomes extend the pass with code rather than with rules: eroded badlands grows stone pillars above the terrain, and the two frozen oceans grow icebergs. Both run here, as they do in Java.</p><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to “Constructors”">​</a></h2><h3 id="constructor" tabindex="-1">Constructor <a class="header-anchor" href="#constructor" aria-label="Permalink to “Constructor”">​</a></h3><blockquote><p><strong>new SurfaceSystem</strong>(<code>randomState</code>): <code>SurfaceSystem</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/ef092b0fc8a9901750f1a809082edca449e0675e/packages/worldgen/src/surface/SurfaceSystem.ts#L154" target="_blank" rel="noreferrer">surface/SurfaceSystem.ts:154</a></p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="randomstate" tabindex="-1">randomState <a class="header-anchor" href="#randomstate" aria-label="Permalink to “randomState”">​</a></h5><p><a href="./RandomState.html"><code>RandomState</code></a></p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>SurfaceSystem</code></p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h2><h3 id="defaultblock" tabindex="-1">defaultBlock <a class="header-anchor" href="#defaultblock" aria-label="Permalink to “defaultBlock”">​</a></h3><blockquote><p><code>readonly</code> <strong>defaultBlock</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/ef092b0fc8a9901750f1a809082edca449e0675e/packages/worldgen/src/surface/SurfaceSystem.ts#L134" target="_blank" rel="noreferrer">surface/SurfaceSystem.ts:134</a></p><p>The dimension&#39;s filler block, which the badlands extension stacks.</p><hr><h3 id="generationcontext" tabindex="-1">generationContext <a class="header-anchor" href="#generationcontext" aria-label="Permalink to “generationContext”">​</a></h3><blockquote><p><code>readonly</code> <strong>generationContext</strong>: <a href="./../#worldgenerationcontext"><code>WorldGenerationContext</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/ef092b0fc8a9901750f1a809082edca449e0675e/packages/worldgen/src/surface/SurfaceSystem.ts#L140" target="_blank" rel="noreferrer">surface/SurfaceSystem.ts:140</a></p><p>The dimension extent a vertical anchor resolves against.</p><hr><h3 id="preliminarysurface" tabindex="-1">preliminarySurface <a class="header-anchor" href="#preliminarysurface" aria-label="Permalink to “preliminarySurface”">​</a></h3><blockquote><p><code>readonly</code> <strong>preliminarySurface</strong>: <a href="./../#densityfunctionnode"><code>DensityFunctionNode</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/ef092b0fc8a9901750f1a809082edca449e0675e/packages/worldgen/src/surface/SurfaceSystem.ts#L138" target="_blank" rel="noreferrer">surface/SurfaceSystem.ts:138</a></p><p>The preliminary surface height function, which is the router&#39;s <code>chunk_surface_level</code>.</p><hr><h3 id="sealevel" tabindex="-1">seaLevel <a class="header-anchor" href="#sealevel" aria-label="Permalink to “seaLevel”">​</a></h3><blockquote><p><code>readonly</code> <strong>seaLevel</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/ef092b0fc8a9901750f1a809082edca449e0675e/packages/worldgen/src/surface/SurfaceSystem.ts#L136" target="_blank" rel="noreferrer">surface/SurfaceSystem.ts:136</a></p><p>The dimension&#39;s sea level.</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="buildsurface" tabindex="-1">buildSurface() <a class="header-anchor" href="#buildsurface" aria-label="Permalink to “buildSurface()”">​</a></h3><blockquote><p><strong>buildSurface</strong>(<code>options</code>): <a href="./../#surfacepass"><code>SurfacePass</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/ef092b0fc8a9901750f1a809082edca449e0675e/packages/worldgen/src/surface/SurfaceSystem.ts#L204" target="_blank" rel="noreferrer">surface/SurfaceSystem.ts:204</a></p><p>Runs the material rule over every column of one chunk, writing into the chunk.</p><p>Columns are walked from the top down, because the stone depth counters and the water height the rules read are accumulated in that order.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="options" tabindex="-1">options <a class="header-anchor" href="#options" aria-label="Permalink to “options”">​</a></h5><p><a href="./../#buildsurfaceoptions"><code>BuildSurfaceOptions</code></a></p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./../#surfacepass"><code>SurfacePass</code></a></p><p>The compiled rule and its context, which the carvers query per carved block.</p><hr><h3 id="getband" tabindex="-1">getBand() <a class="header-anchor" href="#getband" aria-label="Permalink to “getBand()”">​</a></h3><blockquote><p><strong>getBand</strong>(<code>x</code>, <code>y</code>, <code>z</code>): <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/ef092b0fc8a9901750f1a809082edca449e0675e/packages/worldgen/src/surface/SurfaceSystem.ts#L191" target="_blank" rel="noreferrer">surface/SurfaceSystem.ts:191</a></p><p>The terracotta band at one position of a badlands column.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="x" tabindex="-1">x <a class="header-anchor" href="#x" aria-label="Permalink to “x”">​</a></h5><p><code>number</code></p><h5 id="y" tabindex="-1">y <a class="header-anchor" href="#y" aria-label="Permalink to “y”">​</a></h5><p><code>number</code></p><h5 id="z" tabindex="-1">z <a class="header-anchor" href="#z" aria-label="Permalink to “z”">​</a></h5><p><code>number</code></p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h4><p><code>string</code></p><hr><h3 id="getsurfacedepth" tabindex="-1">getSurfaceDepth() <a class="header-anchor" href="#getsurfacedepth" aria-label="Permalink to “getSurfaceDepth()”">​</a></h3><blockquote><p><strong>getSurfaceDepth</strong>(<code>blockX</code>, <code>blockZ</code>): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/ef092b0fc8a9901750f1a809082edca449e0675e/packages/worldgen/src/surface/SurfaceSystem.ts#L180" target="_blank" rel="noreferrer">surface/SurfaceSystem.ts:180</a></p><p>How thick the surface layer is in one column.</p><p>The value is a noise sample plus one quarter of a positional random draw, so two neighboring columns differ by a block or so and the grass line is not flat.</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="blockx" tabindex="-1">blockX <a class="header-anchor" href="#blockx" aria-label="Permalink to “blockX”">​</a></h5><p><code>number</code></p><h5 id="blockz" tabindex="-1">blockZ <a class="header-anchor" href="#blockz" aria-label="Permalink to “blockZ”">​</a></h5><p><code>number</code></p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><hr><h3 id="getsurfacesecondary" tabindex="-1">getSurfaceSecondary() <a class="header-anchor" href="#getsurfacesecondary" aria-label="Permalink to “getSurfaceSecondary()”">​</a></h3><blockquote><p><strong>getSurfaceSecondary</strong>(<code>blockX</code>, <code>blockZ</code>): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/ef092b0fc8a9901750f1a809082edca449e0675e/packages/worldgen/src/surface/SurfaceSystem.ts#L186" target="_blank" rel="noreferrer">surface/SurfaceSystem.ts:186</a></p><p>The second surface noise, which widens a <code>stone_depth</code> condition&#39;s secondary range.</p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="blockx-1" tabindex="-1">blockX <a class="header-anchor" href="#blockx-1" aria-label="Permalink to “blockX”">​</a></h5><p><code>number</code></p><h5 id="blockz-1" tabindex="-1">blockZ <a class="header-anchor" href="#blockz-1" aria-label="Permalink to “blockZ”">​</a></h5><p><code>number</code></p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p>`,86)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};